export interface DecorationArt { mark?: PDFImage; logo?: PDFImage }

/** Embed both PNGs once per document. */
export async function loadDecorationArt(doc: PDFDocument): Promise<DecorationArt> {
  return {
    logo: await doc.embedPng(Buffer.from(LOGO_PNG_BASE64, 'base64')),
    mark: await doc.embedPng(Buffer.from(MARK_PNG_BASE64, 'base64')),
  }
}
